const UNIT_INFO={
  // İngilizce kelime dersleri
  "1-1":"İngilizce'de 'Hello' her zaman kullanılır. 'Good morning' sabah, 'Good evening' akşam içindir. 'How are you?' hal hatır sormaktır; kısa cevabı 'I am fine' (İyiyim).",
  "1-3":"Kendini tanıtırken 'My name is ...' ya da kısaca 'I'm ...' denir. İsim sormak için 'What is your name?'; tanışınca 'Nice to meet you'.",
  "1-5":"Temel sayılar (one, two, three) ve renkler. Renk, ismin önüne gelir: 'a red apple' = kırmızı bir elma.",
  "1-7":"Aile bireyleri ve ev kelimeleri. Sahiplik için 'my' kullanılır: 'my mother' = annem.",
  "1-9":"Nezaket ve sohbet kalıpları. 'Please' (lütfen), 'You're welcome' (bir şey değil), 'Can you help me?' (yardım isterken), 'Don't worry!' (merak etme).",
  "2-2":"Temel yiyecekler ve günlük fiiller (eat, drink, like). Örnek: 'I like tea' = çayı severim.",
  "2-5":"Evdeki eşyalar. Yerini belirtmek için edatlarla kullanılır: 'on the table' = masanın üstünde.",
  "2-8":"Gün ve zaman kelimeleri: 'today' bugün, 'tomorrow' yarın, 'yesterday' dün.",
  "3-7":"Seyahatte gereken kelimeler ve kalıplar. Bir yeri sormak için 'Where is...?' kullanılır.",
  // İtalyanca kelime dersleri
  "it1-1":"'Ciao' hem merhaba hem hoşça kal demektir (samimi). 'Buongiorno' sabah/gündüz, 'Buonasera' akşam kullanılır. 'Come stai?' = nasılsın.",
  "it1-3":"Adını söylemek: 'Mi chiamo ...' (adım ...). Sormak: 'Come ti chiami?'. Tanışınca 'Piacere' (memnun oldum).",
  "it1-5":"1'den 10'a sayılar: uno, due, tre, quattro, cinque ... dieci.",
  "it1-6":"Temel renkler. İtalyanca'da renk genelde ismin sonuna gelir ve cinsiyete uyar: 'libro rosso' = kırmızı kitap.",
  "it1-8":"Aile bireyleri: madre (anne), padre (baba), sorella (kız kardeş), fratello (erkek kardeş), figlio/figlia (oğul/kız).",
  "it1-9":"Günlük kalıplar: Grazie (teşekkür), Un attimo (bir saniye), Mi scusi (affedersiniz), Quanto costa? (ne kadar?), Va bene (tamam).",
  "it1-10":"Sohbette çok geçen kalıplar. 'A dopo' (sonra görüşürüz), 'Per favore' (lütfen), 'Di dove sei?' (nerelisin?), 'Non lo so' (bilmiyorum), 'Sono turco' (Türküm).",
  "it2-2":"Temel yiyecek ve içecekler: pane (ekmek), acqua (su), caffè (kahve), latte (süt), formaggio (peynir).",
  "it2-5":"Evdeki eşyalar: tavolo (masa), sedia (sandalye), porta (kapı), finestra (pencere), letto (yatak).",
  "it2-8":"Gün ve zaman: oggi (bugün), domani (yarın), ieri (dün), lunedì (pazartesi), sabato, domenica.",
  "it2-9":"Günlük rutin eylemleri: mi alzo (kalkarım), colazione (kahvaltı), lezione (ders), compiti (ödev), cena (akşam yemeği).",
  "it3-7":"Seyahat kelimeleri: aeroporto (havalimanı), biglietto (bilet), treno (tren), albergo (otel). 'Dov'è...?' = ... nerede.",
  "it3-8":"Duygu ve sıfatlar: felice (mutlu), triste (üzgün), stanco (yorgun), contento (memnun), bello (güzel).",
  // İngilizce — yeni kelime dersleri
  "1-10":"Gün adları İngilizce'de her zaman büyük harfle yazılır: Monday, Friday. Günden önce 'on' kullanılır: 'on Monday' = pazartesi günü. 'At the weekend' = hafta sonu.",
  "1-11":"Meyve ve sebzeler. Sayılabilenler çoğul olur: 'two bananas', 'three tomatoes' (-o ile bitince -es). 'Grapes' genelde çoğul kullanılır: 'I like grapes.'",
  "1-13":"Vücut kelimeleri. Birden fazlaysa çoğul: 'two eyes', 'two hands'. Düzensiz olanlara dikkat: foot → feet (ayaklar), tooth → teeth (dişler).",
  "1-14":"Kıyafetler. 'Trousers', 'glasses', 'socks', 'shoes' hep çoğul kullanılır: 'My trousers are black.' Giymek: 'I wear a coat.' — üstünü giyinmek: 'put on'.",
  "1-15":"Ay adları da büyük harfle yazılır: January, May. Aydan önce 'in' kullanılır: 'in June' = haziranda. Doğum günü sorarken: 'When is your birthday?'",
  "1-16":"Hava durumu 'It' ile anlatılır: 'It is sunny', 'It is rainy', 'It is cold'. Mevsimden önce 'in' gelir: 'in summer' = yazın.",
  "2-9":"Fiyat sormak: 'How much is it?' (tekil), 'How much are they?' (çoğul). Ödeme: 'Can I pay by card?' ya da 'in cash' (nakit). Beden sorarken: 'What size?'",
  "2-10":"Yol tarifinde emir cümlesi kullanılır: 'Turn left', 'Go straight on'. Sormak için: 'Excuse me, how can I get to the station?' — önce 'Excuse me' demek kibarlıktır.",
  "2-11":"Doktorda derdini anlatmak: 'I have a headache' (başım ağrıyor), 'I have a fever' (ateşim var). Ağrıyan yeri gösterip 'It hurts here' demek yeterli.",
  "2-12":"Günlük rutin geniş zamanla anlatılır: 'I get up at seven.' Saatten önce 'at' gelir. He/She ile fiile -s eklenir: 'She goes to work at eight.'",
  "2-13":"Meslek söylerken 'a' / 'an' unutulmaz: 'I am a teacher', 'She is an engineer' (sesli harfle başladığı için 'an'). Soru: 'What do you do?' = Ne iş yapıyorsun?",
  "3-8":"Otelde: 'I have a reservation' (rezervasyonum var). 'Check in' giriş, 'check out' çıkıştır. İngiltere'de asansöre 'lift', Amerika'da 'elevator' denir.",
  "3-9":"Duygular 'I am / I feel' ile söylenir: 'I am tired', 'I feel lonely'. Dikkat: 'I am bored' = sıkıldım; 'I am boring' = ben sıkıcıyım demektir!",
  "3-11":"Telefonda kibar kalıplar: 'Can I speak to ...?', 'Hold on, please'. Randevu için: 'I'd like to make an appointment.' — 'I'd like' = 'I would like' (isterdim).",
  "3-12":"Restoranda kibar sipariş 'I'd like ...' ile verilir: 'I'd like a soup, please.' Hesabı istemek: 'Can I have the bill, please?' (Amerika'da 'the check').",
  "3-14":"Acil durumda kısa ve net konuş: 'Help!', 'Call an ambulance!', 'Call the police!' Avrupa'da acil numara 112'dir. 'Be careful!' = Dikkat et!",
  "4-2":"İş hayatı kelimeleri. 'Boss' günlük dildir; resmi ortamda 'manager' denir. Fazla mesai: 'I work overtime.' Son tarih: 'The deadline is Friday.'",
  "4-4":"Dükkân adlarında 's genelde 'dükkânı' anlamına gelir: 'the butcher's' = kasap dükkânı, 'the dry cleaner's' = kuru temizlemeci. 'I'm going to the bank.'",
  "4-6":"Fikir bildirmek: 'In my opinion ...' ya da kısaca 'I think ...'. Katılmak 'I agree', katılmamak 'I disagree'. Şaşırınca 'Really?' denir.",
  "4-8":"Ev işlerinde 'do' ve 'make' karışır: 'do the laundry', 'do the shopping' ama 'make the bed'. Bir şey bozuksa: 'It's broken. Can you repair it?'",
  // İtalyanca — yeni kelime dersleri
  "it1-11":"İtalyanca'da her ismin cinsiyeti var: -o ile bitenler çoğunlukla eril (il gatto), -a ile bitenler dişil (la mucca). 'Cane' ve 'ape' -e ile biter; cinsiyetini kelimeyle ezberle.",
  "it1-12":"Vücut kelimelerinde düzensiz çoğullar var: il braccio → le braccia (kollar), il dito → le dita (parmaklar), l'orecchio → le orecchie. 'Capelli' (saç) hep çoğuldur.",
  "it1-13":"Meyve-sebze. -a ile bitenlerin çoğulu -e olur: banana → banane, fragola → fragole. -o ile bitenler -i olur: pomodoro → pomodori.",
  "it1-14":"İtalyanca fiillerin mastarı -are, -ere, -ire ile biter: lavorare, leggere, dormire. Çekimde bu ek düşer: lavoro (çalışırım), leggo (okurum), dormo (uyurum).",
  "it2-10":"Alışverişte fiyat sormak: 'Quanto costa?' (tekil), 'Quanto costano?' (çoğul). Kilo ile istemek: 'Un chilo di pomodori, per favore.' Para üstü = 'il resto'.",
  "it2-11":"Yol tarifi: 'Scusi, dov'è la farmacia?' 'A destra' sağda/sağa, 'a sinistra' solda/sola, 'sempre dritto' dümdüz. Uzak mı diye sormak: 'È lontano?'",
  "it2-13":"Sıcak-soğuk 'fare' fiiliyle anlatılır: 'Fa caldo' (hava sıcak), 'Fa freddo'. Yağış tek fiildir: 'Piove' (yağmur yağıyor), 'Nevica' (kar yağıyor).",
  "it2-14":"Kıyafetler. 'Pantaloni' ve 'calzini' çoğul kullanılır. Denemek: 'Posso provarlo?' (erkek eşya), 'Posso provarla?' (dişil eşya). Beden sormak: 'Che taglia?'",
  "it3-9":"İtalyan yemek düzeni: önce 'primo' (makarna, risotto, çorba), sonra 'secondo' (et, balık), en son 'dolce'. Hesap: 'Il conto, per favore.' Kibar istek: 'Vorrei...'",
  "it3-11":"Otelde: 'Ho una prenotazione' (rezervasyonum var). Kat 'piano' ile söylenir: 'al primo piano' = birinci katta. 'Colazione inclusa?' = Kahvaltı dahil mi?",
  "it3-12":"Saat sormak: 'Che ore sono?' Cevapta 'sono le' + saat: 'Sono le tre' (saat üç). Tek istisna saat bir: 'È l'una'. Buçuk: 'e mezza', çeyrek: 'e un quarto'.",
  "it3-14":"Sevdiğini söylemek: tekil şey/fiil için 'Mi piace' (Mi piace nuotare), çoğul için 'Mi piacciono' (Mi piacciono i film). 'Non mi piace' = sevmem.",
  "it3-15":"Ev işlerinde çoğu kalıp 'fare' ile kurulur: 'fare il bucato' (çamaşır yıkamak), 'fare la spesa' (alışveriş). 'Rifare il letto' = yatağı toplamak.",
  "it4-1":"İş hayatı. 'Capo' günlük dilde amir/patron demektir. 'Ferie' (yıllık izin) hep çoğuldur: 'Vado in ferie' = izne çıkıyorum. 'Andare in pensione' = emekli olmak.",
  "it4-3":"Ağrıyı anlatmak: tekil için 'Mi fa male la testa' (başım ağrıyor), çoğul için 'Mi fanno male i piedi'. Kısa yolu: 'Ho mal di testa'. Acil servis: 'pronto soccorso'.",
  "it4-5":"Trende bileti yolculuktan önce makinede onaylatmak (convalidare) gerekir; yoksa ceza yazılabilir. Gidiş-dönüş: 'andata e ritorno'. 'Sciopero' (grev) ilanlarına dikkat.",
  "it4-8":"Ev ve faturalar. 'Bolletta della luce' = elektrik faturası. Arıza bildirmek: 'C'è un guasto'. Kiracıysan ev sahibine 'il proprietario' denir.",
  "it4-11":"Fikir bildirmek: 'Secondo me ...' (bence). 'Penso di sì' / 'Credo di no' kalıpları çok kullanılır. Katılmak 'Sono d'accordo', karşı çıkmak 'Non sono d'accordo'."
};

